const cfg = $('Config').first().json;
const description = $('Load Description').first().json.description;
const timelineCsv = $('Load Timeline').first().json.timeline;
const risksCsv = $('Load Risks').first().json.risks;
const boardCsv = $('Load Task Board').first().json.task_board;

function parseCsv(text) {
  const rows = [];
  let row = [], field = '', inQ = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQ) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') inQ = false;
      else field += c;
    } else if (c === '"') inQ = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.length > 1 || row[0] !== '') rows.push(row);
      row = [];
    } else field += c;
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row); }
  const header = rows[0].map(h => h.trim());
  return rows.slice(1).map(r =>
    Object.fromEntries(header.map((h, i) => [h, (r[i] ?? '').trim()])));
}

const addDays = (iso, d) => {
  const t = new Date(iso + 'T00:00:00Z');
  t.setUTCDate(t.getUTCDate() + d);
  return t.toISOString().slice(0, 10);
};

const asOf = cfg.as_of_date;
const start = cfg.project_start;

const tasks = parseCsv(boardCsv).map(t => ({
  task_id: t.task_id, task_name: t.task_name, status: t.status,
  assignee: t.assignee, priority: t.priority, sprint: t.sprint,
  due_date: t.due_date, labels: t.labels, description: t.description
}));

const counts = { total: tasks.length };
const by_sprint = {};
for (const t of tasks) {
  counts[t.status] = (counts[t.status] || 0) + 1;
  (by_sprint[t.sprint] = by_sprint[t.sprint] || []).push(t);
}

const notDone = tasks.filter(t => t.status !== 'Done');
const blocked = tasks.filter(t => t.status === 'Blocked');
const overdue = notDone.filter(t => t.due_date < asOf);
const due_soon = notDone.filter(t => t.due_date >= asOf && t.due_date <= addDays(asOf, 7));

const timeline = parseCsv(timelineCsv).map(p => ({
  ...p,
  start_date: addDays(start, (Number(p.start_week) - 1) * 7),
  end_date: addDays(start, Number(p.end_week) * 7 - 1)
}));
const windowEnd = addDays(asOf, 14);
const phases_ending_in_window = timeline.filter(p => p.end_date >= asOf && p.end_date <= windowEnd);
const phases_starting_in_window = timeline.filter(p => p.start_date >= asOf && p.start_date <= windowEnd);

return [{
  json: {
    chat_input: cfg.chatInput,
    config: { as_of_date: asOf, project_start: start, current_sprint: cfg.current_sprint },
    description,
    timeline,
    risks: parseCsv(risksCsv),
    tasks,
    counts,
    by_sprint,
    blocked,
    overdue,
    due_soon,
    phases_ending_in_window,
    phases_starting_in_window
  }
}];

const ctx = $('Assemble Context').first().json;
const raw = $input.first().json.output[0].content[0].text;

let route;
try {
  const m = raw.match(/\{[\s\S]*\}/);
  route = JSON.parse(m ? m[0] : raw);
} catch (e) {
  route = {
    intent: 'other',
    input_source: 'none',
    sprint: null,
    data_sufficient: false,
    missing_fields: ['could not understand the request']
  };
}

const intents = ['plan', 'risk', 'status', 'milestone', 'comms', 'other'];
if (!intents.includes(route.intent)) route.intent = 'other';

const route_key = (route.data_sufficient === true && route.intent !== 'other')
  ? route.intent
  : 'clarify';

return [{ json: { ...ctx, route, route_key } }];

const r = $json.route || {};
const missing = (r.missing_fields || []).join(', ');
let msg;

if (r.intent === 'plan') {
  msg = "I can't build a project plan from this yet, because there isn't enough detail and I won't invent scope or goals. Please share: "
    + (missing || 'scope, goals, deliverables, timeline and team size') + '.';
} else if (r.intent === 'risk') {
  msg = "I can't produce a risk assessment yet, because I don't know what the project is. Please share: "
    + (missing || 'the project description, scope, timeline and team') + '.';
} else if (r.intent === 'status') {
  msg = "No task data is available, so I can't produce a status report. I won't make up task statuses or progress percentages. Please share the task board (task names, statuses and sprint).";
} else if (r.intent === 'milestone') {
  msg = "I need the project timeline or task board to answer that. Please share it"
    + (missing ? ' (missing: ' + missing + ')' : '') + '.';
} else if (r.intent === 'comms') {
  msg = "I need the sprint tasks to write that update. Please tell me which sprint and share the task data.";
} else {
  msg = "I can help with project plans, risk assessments, status reports, upcoming milestones and stakeholder updates. Which would you like, and for which project?";
}

return [{ json: { output: msg } }];

