for (const t of tasks) counts[t.status] = (counts[t.status] || 0) + 1;
const overdue = tasks.filter(t => t.status !== 'Done' && t.due_date < asOf);
return [{ json: { ...j, comms_sprint: sprint, comms_tasks: tasks, comms_counts: counts, comms_overdue: overdue } }];

